searches.primary_spl:
`notable` urgency IN ("high","critical") earliest=-30d
| eval incident_id=rule_name."|"._time
| join incident_id type=left [
    search index=itsm sourcetype="snow:incident" earliest=-30d
    | eval incident_id=correlation_id
    | eval stages_complete=mvcount(mvappend(
        if(match(work_notes,"(?i)contain"),"contain",""),
        if(match(work_notes,"(?i)erad"),"erad",""),
        if(match(work_notes,"(?i)recover"),"recover",""),
        if(match(work_notes,"(?i)lessons"),"lessons","")))
    | stats latest(stages_complete) as stages_complete by incident_id
]
| eval playbook_gap=if(stages_complete < 4, 1, 0)
| where playbook_gap=1 AND status!="Closed"
| table _time, rule_name, status, owner, stages_complete

index=itsm sourcetype="snow:change_request" state IN ("Implement","Closed") earliest=-60d
| eval missing=mvjoin(
    if(isnull(u_impact_analysis) OR u_impact_analysis="","impact",null()),
    if(isnull(u_rollback_plan) OR u_rollback_plan="","rollback",null()),
    if(isnull(u_security_review) OR u_security_review="false","sec_review",null()),
    ",")
| where missing!=""
| stats count by missing, cmdb_ci
| sort - count

index=business sourcetype="expense_reports" earliest=-90d
| eval anomaly_flags=mvappend(
    if(amount=round(amount,0) AND amount>=100, "ROUND_NUMBER", null()),
    if(amount>=490 AND amount<500, "JUST_BELOW_THRESHOLD", null()),
    if(tonumber(strftime(strptime(expense_date,"%Y-%m-%d"),"%u"))>=6, "WEEKEND", null()),
    if(receipt_attached="no" AND amount>25, "NO_RECEIPT", null()))
| eventstats avg(amount) as dept_avg, stdev(amount) as dept_stdev by department, category
| eval statistical_outlier=if(amount > dept_avg + 2*dept_stdev, "STATISTICAL_OUTLIER", null())
| eval anomaly_flags=mvappend(anomaly_flags, statistical_outlier)
| where isnotnull(anomaly_flags)
| stats count as flagged_expenses, sum(amount) as total_flagged_amount, values(anomaly_flags) as reasons by employee_id, department
| sort - total_flagged_amount
| table employee_id, department, flagged_expenses, total_flagged_amount, reasons
